class SharedBuffer {
private:
    std::vector<int> data_;
    std::mutex mtx_;
    std::atomic<bool> initialized_{false};

public:
    void initialize() {
        std::lock_guard<std::mutex> lock(mtx_);
        if (!initialized_.load()) {
            data_ = {1, 2, 3, 4, 5};
            initialized_.store(true);
        }
    }

    int getElement(size_t index) {
        std::lock_guard<std::mutex> lock(mtx_);
        if (!initialized_.load()) {
            return -1;  // 未初始化，返回错误码
        }
        if (index >= data_.size()) {
            return -1;  // 越界检查，防止 CWE-125
        }
        return data_[index];  // line 24: 安全访问
    }
};

int main() {
    SharedBuffer buffer;
    buffer.initialize();

    std::vector<std::thread> threads;
    for (int i = 0; i < 4; ++i) {
        threads.emplace_back([&buffer]() {
            for (size_t idx = 0; idx < 10; ++idx) {
                int val = buffer.getElement(idx);
                if (val == -1) {
                    std::cout << "Invalid access at index " << idx << "\n";
                } else {
                    std::cout << "Value: " << val << "\n";
                }
            }
        });
    }

    for (auto& t : threads) {
        t.join();
    }
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    char *data;
    size_t len;
    pthread_mutex_t lock;
} Buffer;

Buffer *buffer_create(size_t size) {
    Buffer *buf = (Buffer *)malloc(sizeof(Buffer));
    if (!buf) return NULL;
    buf->data = (char *)malloc(size);
    if (!buf->data) {
        free(buf);
        return NULL;
    }
    buf->len = size;
    pthread_mutex_init(&buf->lock, NULL);
    return buf;
}

void buffer_destroy(Buffer *buf) {
    if (!buf) return;
    pthread_mutex_lock(&buf->lock);
    free(buf->data);
    buf->data = NULL;  // 防御：置NULL防止悬垂指针
    buf->len = 0;
    pthread_mutex_unlock(&buf->lock);
    pthread_mutex_destroy(&buf->lock);
    free(buf);         // 防御：释放后置NULL
    buf = NULL;        // 局部变量置NULL（实际无效但语义明确）
}

int buffer_write(Buffer *buf, const char *src, size_t n) {
    if (!buf || !src) return -1;
    pthread_mutex_lock(&buf->lock);
    if (buf->data == NULL) {  // 防御：检查已释放状态
        pthread_mutex_unlock(&buf->lock);
        return -1;
    }
    if (n > buf->len) {       // 防御：边界检查
        pthread_mutex_unlock(&buf->lock);
        return -1;
    }
    memcpy(buf->data, src, n);
    pthread_mutex_unlock(&buf->lock);
    return 0;
}

int main(void) {
    Buffer *b = buffer_create(64);
    if (!b) return 1;
    buffer_write(b, "hello", 5);
    buffer_destroy(b);
    // b 已释放，后续不再使用（RAII 语义由调用者保证）
    return 0;
}

// Flask 文件上传处理 - 用户头像上传功能
const express = require('express');
const multer = require('multer');
const path = require('path');
const fs = require('fs');
const router = express.Router();

// 配置 multer 存储
const storage = multer.diskStorage({
  destination: (req, file, cb) => {
    cb(null, 'uploads/');
  },
  filename: (req, file, cb) => {
    // 生成随机文件名，避免路径遍历
    const uniqueSuffix = Date.now() + '-' + Math.round(Math.random() * 1E9);
    cb(null, uniqueSuffix + path.extname(file.originalname));
  }
});

// 文件类型白名单
const allowedTypes = ['.jpg', '.jpeg', '.png', '.gif'];
const maxSize = 5 * 1024 * 1024; // 5MB

const upload = multer({
  storage: storage,
  limits: { fileSize: maxSize },
  fileFilter: (req, file, cb) => {
    // 检查扩展名（白名单）
    const ext = path.extname(file.originalname).toLowerCase();
    if (!allowedTypes.includes(ext)) {
      return cb(new Error('Invalid file type'));
    }
    // 检查 MIME 类型
    if (!file.mimetype.startsWith('image/')) {
      return cb(new Error('Not an image'));
    }
    cb(null, true);
  }
});

// 文件上传处理路由
router.post('/avatar', upload.single('avatar'), (req, res) => {
  if (!req.file) {
    return res.status(400).json({ error: 'No file uploaded' });
  }

  // 获取用户ID（从认证中间件）
  const userId = req.user.id;

  // 验证文件内容（读取前几个字节检查魔数）
  const filePath = req.file.path;
  const buffer = fs.readFileSync(filePath);

  // 检查 PNG/JPEG/GIF 魔数
  const isPNG = buffer.length > 8 && 
    buffer[0] === 0x89 && buffer[1] === 0x50 && 
    buffer[2] === 0x4E && buffer[3] === 0x47;
  const isJPEG = buffer.length > 3 && 
    buffer[0] === 0xFF && buffer[1] === 0xD8 && buffer[2] === 0xFF;
  const isGIF = buffer.length > 6 && 
    buffer.toString('ascii', 0, 3) === 'GIF';

  if (!isPNG && !isJPEG && !isGIF) {
    fs.unlinkSync(filePath); // 删除无效文件
    return res.status(400).json({ error: 'Invalid image content' });
  }

  // 构造安全的文件路径（不使用用户输入拼接）
  const userDir = path.join('uploads', String(userId));
  if (!fs.existsSync(userDir)) {
    fs.mkdirSync(userDir, { recursive: true });
  }

  const finalPath = path.join(userDir, req.file.filename);

  // 移动文件到用户目录（使用 fs.rename，不拼接用户输入）
  fs.renameSync(filePath, finalPath);

  // 返回文件访问 URL（固定前缀，不包含用户可控路径）
  res.json({ 
    url: `/uploads/${userId}/${req.file.filename}`,
    size: req.file.size
  });
});

// 错误处理中间件
router.use((err, req, res, next) => {
  if (err instanceof multer.MulterError) {
    return res.status(400).json({ error: err.message });
  }
  if (err.message === 'Invalid file type' || err.message === 'Not an image') {
    return res.status(400).json({ error: err.message });
  }
  res.status(500).json({ error: 'Internal server error' });
});

module.exports = router;

